/* Inside Nemotron 3. All numerical animations are illustrative; architecture
   dimensions and layer order are from the pinned NVIDIA configuration below. */
'use strict';
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const term = (key, label = key) => `<button class="term" data-term="${key}" type="button">${label}</button>`;
const sources = {
  super: ['Super technical report · §§2.1–2.2', 'https://research.nvidia.com/labs/nemotron/files/NVIDIA-Nemotron-3-Super-Technical-Report.pdf'],
  config: ['NVIDIA model configuration · pinned revision', 'https://huggingface.co/nvidia/NVIDIA-Nemotron-3-Super-120B-A12B-BF16/blob/a9f80fc8bdaa9ad2104cac1fd895cfa06daa8fe8/config.json'],
  modelCode: ['Super model implementation · pinned revision', 'https://huggingface.co/nvidia/NVIDIA-Nemotron-3-Super-120B-A12B-BF16/blob/a9f80fc8bdaa9ad2104cac1fd895cfa06daa8fe8/modeling_nemotron_h.py'],
  mamba: ['Mamba-2 paper · Dao & Gu', 'https://proceedings.mlr.press/v235/dao24a.html'],
  mambaCode: ['Mamba-2 implementation · state-spaces', 'https://github.com/state-spaces/mamba/blob/main/mamba_ssm/modules/mamba2.py'],
  ssd: ['SSD algorithm · author’s explanation', 'https://tridao.me/blog/2024/mamba2-part3-algorithm/'],
  gqa: ['Grouped-query attention paper', 'https://arxiv.org/abs/2305.13245'],
  attention: ['Attention Is All You Need · §3', 'https://arxiv.org/abs/1706.03762'],
  latent: ['LatentMoE technical paper', 'https://arxiv.org/abs/2601.18089'],
  family: ['NVIDIA Nemotron 3 family', 'https://research.nvidia.com/labs/nemotron/Nemotron-3/'],
  recipes: ['NVIDIA’s open training recipes', 'https://github.com/NVIDIA-NeMo/Nemotron/tree/main/docs/nemotron/super3'],
  nano: ['Nano architecture · NVIDIA', 'https://github.com/NVIDIA-NeMo/Nemotron/blob/main/skills/nemotron-nano3/paper/architecture.md'],
  blog: ['Your starting article · Kubesimplify', 'https://blog.kubesimplify.com/nemotron3-on-dgx-spark'],
  precision: ['NVIDIA Super quantization guide', 'https://github.com/NVIDIA-NeMo/Nemotron/blob/main/docs/nemotron/super3/quantization.md'],
  train: ['NVIDIA Super pretraining guide', 'https://github.com/NVIDIA-NeMo/Nemotron/blob/main/docs/nemotron/super3/pretrain.md'],
  sft: ['NVIDIA Super fine-tuning guide', 'https://github.com/NVIDIA-NeMo/Nemotron/blob/main/docs/nemotron/super3/sft.md'],
  rl: ['NVIDIA Super reinforcement learning guides', 'https://github.com/NVIDIA-NeMo/Nemotron/tree/main/docs/nemotron/super3/rl']
};
const glossary = [
  ['LLM','Large language model','A neural network trained to predict and generate sequences of tokens. Nemotron 3 is a family of LLMs.'],
  ['Token','A piece of text','A vocabulary entry: often a word fragment, punctuation or a special marker. Tokens are not always whole words.'],
  ['Embedding','A learned numerical representation','A lookup table turns a token ID into a vector. This is the starting representation, which later layers refine.'],
  ['Vector','An ordered list of numbers','One token’s representation has many coordinates. A coordinate is not normally a neatly named human concept.'],
  ['Parameter','A learned model number','A weight learned during training. Parameters are different from temporary activations produced for a particular prompt.'],
  ['Activation','A temporary computed value','A representation produced as data passes through the model. Expert routing selects computation using activations.'],
  ['Projection','A learned matrix multiplication','A transformation of a vector into a different representation or number of coordinates. Down-projection reduces its width.'],
  ['SSM','State-space model','A sequence model that updates a hidden state and reads an output from it. Mamba uses an input-dependent, selective SSM.'],
  ['State','A running numerical memory','A fixed-shape collection of values updated as tokens arrive. Fixed shape means fixed storage size, not unchanged contents.'],
  ['Recurrence','An update using the previous state','The current state depends on the old state and the current input. This naturally preserves sequence order.'],
  ['Selectivity','Input-dependent memory control','Mamba changes how it writes, retains and reads information according to the current token representation.'],
  ['Δ','Delta · an input-dependent time step','In Mamba, a learned positive step size controls the state update. Larger steps generally allow faster decay and stronger change.'],
  ['SSD','Structured state-space duality','A relationship between a class of state-space recurrences and structured matrix operations. Mamba-2 uses it for efficient computation.'],
  ['Convolution','A learned local mixing operation','A small window mixes nearby token features. A causal convolution uses only the current token and preceding tokens.'],
  ['SiLU','Sigmoid linear unit','A smooth nonlinear activation: x multiplied by sigmoid(x). Used in the Mamba block’s local feature processing.'],
  ['ReLU','Rectified linear unit','The activation max(0,x). Squared ReLU squares this result; Super uses squared ReLU in its expert feed-forward networks.'],
  ['Sigmoid','A smooth function from real numbers to 0–1','Computes 1 / (1 + exp(−x)). Unlike softmax, separate sigmoid scores do not automatically sum to one.'],
  ['Load balancing','Spread routed work across experts','Training mechanisms discourage too many tokens from choosing the same experts, avoiding overloaded experts and underused model capacity.'],
  ['Positional embedding','An explicit position representation','A vector or transformation that encodes a token’s position. Super’s attention implementation does not add a positional embedding or apply rotary position encoding.'],
  ['GQA','Grouped-query attention','Several query heads share a key and value head. Super has 32 query heads sharing 2 key/value heads.'],
  ['MHA','Multi-head attention','Attention with a separate set of query, key and value projections for each head. A comparison baseline in this guide.'],
  ['MQA','Multi-query attention','All query heads share one key/value head. GQA lies between MQA and ordinary multi-head attention.'],
  ['Q / K / V','Query / key / value','Query: what to look for. Key: what a token offers for matching. Value: the information to mix when a match gets weight.'],
  ['Head','One learned attention or state channel','Parallel paths let the model combine different transformations. A head is not assigned a fixed human role.'],
  ['Softmax','A scores-to-weights function','Exponentiates scores and divides by their sum, producing positive weights that add to one.'],
  ['Causal mask','A rule blocking future tokens','During prediction, a token can use itself and earlier tokens, but cannot use later tokens.'],
  ['KV cache','Key/value cache','Stored keys and values from previous tokens. It avoids recomputing those projections during generation and grows with context length.'],
  ['MoE','Mixture of experts','Many feed-forward networks are available; a router chooses a small subset for each token. Experts are learned networks, not separate chatbots.'],
  ['LatentMoE','Mixture of experts in a smaller representation','Routed experts process a compressed vector; learned projections connect it to the full model width. The router and shared expert remain at full width.'],
  ['Router','A learned expert selector','Produces scores for available experts from a token’s representation. The highest scoring experts are selected.'],
  ['Top-k','Choose the k highest scores','Super selects 22 routed experts per token from 512 available experts in an expert layer.'],
  ['Shared expert','An expert used by every token','A full-width feed-forward path complements the selected routed experts. Super’s config includes one shared expert.'],
  ['FFN','Feed-forward network','Transforms each token’s features independently. Also called an MLP, or multilayer perceptron. It does not itself mix different token positions.'],
  ['RMSNorm','Root mean square normalization','Rescales a vector using the root mean square of its coordinates and a learned scale, helping control activation magnitude.'],
  ['Residual','A shortcut around a transformation','Adds a layer’s output back to its input, helping information and gradients flow through a deep stack.'],
  ['MTP','Multi-token prediction','Additional training and prediction paths for future tokens. They can draft candidate tokens for verification by the main model.'],
  ['Autoregressive','Generate using previous tokens','Predict a token, append it to the sequence, then predict again using the expanded context.'],
  ['Prefill','Process the prompt','The initial pass over the prompt creates the states and caches needed for subsequent generation.'],
  ['Decode','Generate the continuation','Successive prediction steps use the prompt plus already generated tokens.'],
  ['NVFP4','NVIDIA’s 4-bit floating-point format','Low-precision values with scaling metadata and hardware support. Mixed precision keeps sensitive operations in higher precision.'],
  ['BF16','16-bit brain floating point','A floating-point number format used for training and storage. Its exponent range resembles 32-bit floating point, with fewer fraction bits.'],
  ['FP8','8-bit floating point','A lower precision format that can reduce weight storage and speed suitable matrix operations.'],
  ['FLOP','Floating-point operation','One arithmetic operation on floating-point numbers. FLOP counts alone do not describe memory traffic, latency or communication.'],
  ['SFT','Supervised fine-tuning','Training on example prompts and desired responses to teach instruction following and response style.'],
  ['RL','Reinforcement learning','Training using rewards on generated behavior, such as checked code correctness or human preference.'],
  ['RLVR','Reinforcement learning with verifiable rewards','A form of reinforcement learning where an external check, such as a test or math verifier, can evaluate an answer.'],
  ['Context','Tokens available to the model','The prompt and generated continuation within the supported context window. Capacity is not a guarantee of perfect recall.']
];

const nodes = {
  tokens:{parent:'overview',label:'From text to vectors',title:'First, give text a numerical form.',color:'mint',icon:'Aa',intro:`The model never processes letters directly. A ${term('Token','tokenizer')} maps text to vocabulary IDs; an ${term('Embedding','embedding')} turns each ID into a vector.`,takeaway:'Every position starts with a vector. The rest of the network repeatedly transforms these vectors.',sim:'tokens',children:['tokenizer','embedding','output'],sections:[['A token is a text piece','“Unbelievable” might be several tokens. Whitespace, punctuation and special conversation markers also matter. The pieces shown here are examples, not the actual tokenizer output.'],['Width is different from length','Sequence length counts token positions. Model width counts numbers at each position. Super’s model width is 4,096; its public vocabulary config has 131,072 entries.']],refs:['config'],next:'stack'},
  tokenizer:{parent:'tokens',label:'Tokenization',title:'Text pieces become vocabulary IDs.',color:'mint',intro:'A tokenizer applies a fixed vocabulary and splitting procedure. The resulting integer IDs identify entries; their numerical order has no semantic meaning.',takeaway:'Token ID 42 is an address in a table, not “twice as meaningful” as token ID 21.',flow:[['Text','“The sky is blue.”'],['Tokenizer','Split + look up pieces'],['IDs','An ordered sequence']],sections:[['Subwords keep the vocabulary manageable','A model can combine familiar fragments to represent uncommon words. Token counts vary across languages and text types.'],['Conversation formatting is also input','Role markers, end markers and tool messages become part of the token sequence. They help distinguish instructions, responses and tool results.']],refs:['config'],children:['embedding']},
  embedding:{parent:'tokens',label:'Embedding & dimensions',title:'One ID becomes 4,096 numbers.',color:'mint',intro:`An ${term('Embedding','embedding')} table contains a learned vector for each vocabulary entry. Look up a row for each token, preserving sequence order.`,takeaway:'The starting vector encodes useful learned features; contextual meaning emerges as it passes through the stack.',sim:'embedding',sections:[['Learned during training','The embedding coordinates change when training updates the model. Similar uses can create useful relationships, but individual coordinates need not have a readable label.'],['Context changes the representation','“Bank” starts with the same token embedding wherever that token occurs. Later token-mixing layers can distinguish a river bank from a financial bank using context.']],refs:['config','attention'],children:['stack']},
  stack:{parent:'overview',label:'The hybrid stack',title:'88 layers. Three kinds of work.',color:'mint',intro:`${term('SSM','Mamba-2')} and attention mix information across positions. ${term('LatentMoE','Expert layers')} transform the features at each position. These operations are interleaved through the depth of the model.`,takeaway:'The layer types cooperate: recurrent memory, direct context lookup, and sparse feature computation.',sim:'stack',children:['mamba','attention','moe','residual'],sections:[['This is the actual released pattern','The pinned config encodes M for Mamba, E for experts and * for attention. Counting it yields 40 Mamba, 40 expert and 8 attention layers. The eight attention anchors occur at layers 8, 17, 26, 37, 48, 59, 70 and 79.'],['“Layer” counts can be misleading','Here, a Mamba operation, an attention operation and an expert operation each count as a layer. The 88 does not mean 88 full conventional Transformer blocks.']],refs:['config'],next:'mamba'},
  residual:{parent:'stack',label:'Residuals & normalization',title:'Keep a useful path through depth.',color:'mint',intro:`Deep networks need controlled numerical scales and a reliable path for information. ${term('RMSNorm')} and ${term('Residual','residual connections')} help provide both.`,takeaway:'A layer learns a change to the representation; the shortcut carries the current representation forward.',sim:'residual',sections:[['RMSNorm stabilizes scale','Compute the root mean square of a vector’s coordinates, divide by it with a small numerical safety term, then apply a learned scale. Unlike LayerNorm, it does not subtract the mean.'],['The residual path makes refinement easier','A typical conceptual update is x + F(RMSNorm(x)). The actual checkpoint can rescale its prenormalized residuals, so the illustration shows the principle rather than all implementation factors.']],refs:['config','super']},
  mamba:{parent:'stack',label:'Mamba-2',title:'Carry a memory. Update it as you read.',color:'mint',icon:'≈',intro:`Mamba-2 is a selective ${term('SSM','state-space model')}. Each incoming token updates a numerical ${term('State','state')}; the layer reads its output from that state.`,takeaway:'Past information is folded into a fixed-shape memory, rather than retaining a separate key and value for every past token.',sim:'mamba',children:['state','selectivity','mamba-block','ssd'],sections:[['Read → update → read out','The input determines what gets written and how memory changes. The updated state produces features for the next layer. The memory tiles are an illustration of numbers, not a literal list of remembered facts.'],['A useful tradeoff','Generation needs constant state storage per Mamba layer as the sequence grows. That compressed state can lose details; attention anchors add direct access to earlier token representations.']],refs:['mamba','mambaCode'],quiz:['If the prompt gets twice as long, what happens to a Mamba layer’s recurrent state shape?',['It doubles.','It stays fixed, while its values change.','It stores every previous token.'],1,'The state has a fixed shape. Its contents change at every token; prompt processing still takes more work for a longer prompt.'],next:'attention'},
  state:{parent:'mamba',label:'The state update',title:'Retain some memory. Write something new.',color:'mint',intro:`A ${term('Recurrence','recurrence')} updates memory using old memory and the current input. In Mamba-2, each head maintains a state matrix.`,takeaway:'The equations describe learned numerical transformations. “Remember” and “forget” are useful analogies for those transformations.',sim:'state',sections:[['A simplified discrete equation','hₜ = aₜ hₜ₋₁ + bₜ xₜ; yₜ = cₜ hₜ + D xₜ. Here h is the state, x the input, a the retention factor, b the write direction and c the read direction. The real implementation uses head and state dimensions, not one scalar.'],['Mamba-2 restricts the transition structure','Within a head, the decay is scalar across state coordinates. This structured transition is central to the efficient SSD algorithm. Super uses 128 Mamba heads, head width 64 and state dimension 128; the tiny diagram omits most coordinates.']],refs:['mamba','config'],children:['selectivity','ssd']},
  selectivity:{parent:'mamba',label:'Input-dependent selection',title:'The token helps control the memory.',color:'mint',intro:`A fixed state update would treat every input with the same memory dynamics. Mamba instead derives its write/read vectors and ${term('Δ','time step Δ')} from the current input.`,takeaway:'Selectivity lets the network learn when and how to change its running representation.',sim:'selectivity',sections:[['Δ controls the timescale','A learned positive Δ discretizes a continuous-time transition. With a negative learned decay rate A, the discrete retention factor is exp(ΔA): a larger Δ causes stronger decay.'],['B and C control writing and reading','Input-dependent B vectors shape the write into memory. C vectors read information back out. These are continuous learned values, not a hard decision that a whole word is important or unimportant.']],refs:['mambaCode','mamba'],children:['mamba-block']},
  'mamba-block':{parent:'mamba',label:'Inside a Mamba block',title:'The state update lives inside a full block.',color:'mint',intro:`The ${term('SSM')} is the core. Learned projections, a short causal ${term('Convolution','convolution')}, activation functions and gating prepare its inputs and shape its output.`,takeaway:'Mamba-2 combines local mixing, long-running state and a learned gate before returning to model width.',flow:[['Project','Create x, B, C, Δ and a gate'],['Local mix','Causal convolution + SiLU'],['State update','Selective SSM / SSD'],['Gate + project','Return to model width']],sections:[['A short local window','Super’s config uses convolution width 4. Local convolution can combine a token’s features with those of nearby predecessors, before the state model handles longer history.'],['Gate and return','A learned gate modulates the SSM output, with normalization and an output projection. SiLU (sigmoid linear unit) is a smooth activation x·sigmoid(x); it makes the block nonlinear.']],refs:['mambaCode','config'],children:['ssd']},
  ssd:{parent:'mamba',label:'Why Mamba-2 is fast',title:'One computation. Two useful views.',color:'mint',intro:`${term('SSD','Structured state-space duality')} connects a structured recurrence to a structured matrix form. Mamba-2 uses that relationship to process chunks efficiently on GPUs.`,takeaway:'Sequential generation and parallel prompt processing are two execution strategies for the same sequence transformation.',flow:[['Within chunks','Parallel matrix operations'],['Across chunks','Pass compact boundary states'],['Combine','Recover the sequence outputs']],sections:[['During generation','One new token updates the existing state. The work and cache size for that recurrent update do not grow with the number of earlier tokens.'],['During prompt processing or training','The chunk algorithm uses matrix multiplication inside chunks and propagates state between chunks. It avoids materializing a full dense all-pairs attention matrix. Fixed dimensions give linear scaling with sequence length.']],refs:['ssd','mamba'],next:'attention'},
  attention:{parent:'stack',label:'GQA attention',title:'Sometimes, look back directly.',color:'blue',icon:'⌕',intro:`Attention lets the current token weight earlier token representations directly. ${term('GQA','Grouped-query attention')} keeps many query heads while sharing key/value heads.`,takeaway:'Super’s 32 query heads share 2 key/value heads: 16 query heads per group.',sim:'attention',children:['qkv','grouping','mask'],sections:[['Direct retrieval from context','A query is compared against keys; normalized matching scores weight the values. Different heads learn different projections. The heatmap shows an illustrative causal attention pattern.'],['Eight global anchors','Only eight of the 88 layers use attention. Their access to earlier positions complements Mamba’s compressed recurrent memory. GQA reduces the stored keys and values in these layers.']],refs:['gqa','config'],quiz:['What does GQA share?',['The output of every query head.','The key and value heads across groups of query heads.','One state for all past tokens.'],1,'Query heads remain separate. Groups share their keys and values, reducing KV storage and bandwidth.'],next:'moe'},
  qkv:{parent:'attention',label:'Queries, keys & values',title:'Match first. Mix second.',color:'blue',intro:`Three learned projections turn token vectors into ${term('Q / K / V','queries, keys and values')}. Their names describe how the projected vectors are used.`,takeaway:'Attention weights say how much of each value vector contributes to a query’s result.',sim:'qkv',sections:[['Scores become weights','For each head, dot products QKᵀ measure alignment. Divide by √dₕ to control score magnitude, apply the causal mask, then softmax across available positions.'],['Values carry the result','Multiply those weights by V to make a weighted sum. Concatenate the head outputs and apply an output projection. A strong attention weight is not a complete explanation of the model’s final answer.']],refs:['attention'],children:['mask','grouping']},
  mask:{parent:'attention',label:'Causality & softmax',title:'A prediction can only use its past.',color:'blue',intro:`The ${term('Causal mask','causal mask')} blocks future positions. ${term('Softmax')} converts the remaining scores into positive weights summing to one.`,takeaway:'A model can train on a full sequence in parallel while preventing each prediction from seeing the answer ahead.',sim:'mask',sections:[['The triangular rule','Row t can attend to columns 1 through t, depending on the prediction indexing convention. Future columns are masked before softmax.'],['Why this matches generation','At inference there are no future tokens yet. During training, masking recreates that information restriction for all positions at once.']],refs:['attention']},
  grouping:{parent:'attention',label:'GQA vs ordinary attention',title:'32 ways to ask. Two sets of memory.',color:'blue',intro:`Ordinary ${term('MHA','multi-head attention')} pairs each query head with its own key/value head. GQA lets a group of query heads share one key/value head.`,takeaway:'At equal head width and sequence length, 2 KV heads store 1/16 as many KV elements as 32 KV heads.',sim:'grouping',sections:[['The query paths stay distinct','Super has 32 query heads and 2 KV heads, each with head dimension 128. Query projections differ even when the underlying key/value cache is shared.'],['The savings have a precise scope','The 16× factor applies to KV elements relative to a 32-KV-head baseline. It is not a 16× reduction in total model memory or all attention computation. GQA still performs causal context lookup.']],refs:['gqa','config'],children:['memory']},
  moe:{parent:'stack',label:'LatentMoE',title:'More experts. A smaller working space.',color:'violet',icon:'⋮',intro:`${term('MoE','Mixture of experts')} gives each token a choice of feed-forward networks. ${term('LatentMoE')} makes the routed expert path narrower, so expert computation and transfer can cost less.`,takeaway:'Super compresses 4,096 coordinates to 1,024, selects 22 of 512 routed experts, combines their outputs, and restores the model width.',sim:'moe',children:['routing','projection','expert'],sections:[['Two parallel paths','Routed experts operate in the 1,024-dimensional latent space. The learned router and shared expert stay at full model width. One shared expert runs for every token alongside the selected routed experts.'],['Use the saved bandwidth','Narrower routed inputs and outputs reduce transfer and per-expert matrix size. LatentMoE uses that budget for more available and more active experts; total runtime still depends on kernels, batch size and hardware.']],refs:['latent','config'],quiz:['Which parts stay in the full 4,096-dimensional representation?',['Only the routed experts.','The router and shared expert.','Nothing; the whole model becomes 1,024-wide.'],1,'The routed expert path is compressed. The router, shared expert and other model layers remain full width.'],next:'mtp'},
  routing:{parent:'moe',label:'Routing & top-22',title:'Choose a small set for each token.',color:'violet',intro:`A ${term('Router','router')} scores experts using the token’s current representation. ${term('Top-k','Top-22')} routing selects 22 of the 512 routed experts in that layer.`,takeaway:'Different tokens, layers and contexts can select different expert combinations. Experts are not manually labeled “math” or “English.”',sim:'routing',sections:[['Weighted combination','The selected experts transform the latent representation. Their outputs are combined using routing weights, then projected back to model width. The checkpoint normalizes selected routing probabilities and uses a routed scaling factor.'],['Capacity is larger than active work','Most routed experts do not execute for a particular token, but their weights still exist and must be stored somewhere. Routing also creates dispatch and balancing work in distributed systems.']],refs:['config','latent'],children:['expert','projection']},
  projection:{parent:'moe',label:'The latent bottleneck',title:'Compress → compute → restore.',color:'violet',intro:`“Latent” means an internal learned representation. Two learned ${term('Projection','projections')} connect the full-width stream and the smaller routed expert space.`,takeaway:'The bottleneck is learned, so training can decide which combinations of features deserve room in the routed path.',sim:'projection',sections:[['The shapes make the idea concrete','Down-projection maps 4,096 → 1,024; up-projection maps 1,024 → 4,096. In between, each routed expert expands to its internal hidden width of 2,688 and maps back to 1,024.'],['Compression has a tradeoff','A smaller vector cannot preserve every arbitrary full-width detail. The full-width shared expert and residual stream provide additional paths, while training optimizes the useful transformations. Four times narrower does not mean four times faster end to end.']],refs:['config','latent'],children:['expert']},
  expert:{parent:'moe',label:'What an expert computes',title:'An expert is a small neural network.',color:'violet',intro:`An expert is a ${term('FFN','feed-forward network')}: learned matrices with a nonlinear activation between them. It transforms one token’s features, rather than looking up other token positions.`,takeaway:'The experts add conditional feature computation; Mamba and attention provide the mixing across token positions.',flow:[['Input','Latent vector · 1,024'],['Expand','Hidden features · 2,688'],['Activate','Squared ReLU'],['Contract','Latent vector · 1,024']],sections:[['A nonlinear feature transform','Squared ReLU (rectified linear unit) computes max(0,z)² between the expert’s two linear transformations. A nonlinear function allows more than a single combined matrix multiplication.'],['Shared and routed roles','The shared expert uses the full 4,096-wide input with hidden width 5,376. It runs for every token. The 22 routed experts supply additional conditional transformations in latent space.']],refs:['config'],children:['residual']},
  mtp:{parent:'overview',label:'Predicting ahead',title:'Draft a few tokens. Verify them together.',color:'gold',icon:'↠',intro:`${term('MTP','Multi-token prediction')} adds future-token objectives and an internal drafting path. At inference, draft tokens can be checked by the main model in a verification pass.`,takeaway:'Speculation accelerates generation when enough draft tokens are accepted; it still needs a correct verification procedure.',sim:'mtp',children:['output','speculation'],sections:[['A training objective and an inference tool','Learning to predict future offsets encourages representations useful beyond just the next token. The trained path can then propose a continuation.'],['Shared prediction weights','The Super report describes parameter sharing across MTP training offsets to support repeated autoregressive drafting. The exported number of prediction modules is checkpoint dependent; two training offsets do not mean a hard two-token drafting limit.']],refs:['super','config'],next:'inference'},
  speculation:{parent:'mtp',label:'Speculative decoding',title:'A draft is a proposal, not a promise.',color:'gold',intro:'Draft several tokens cheaply, verify the candidates with the main model, accept a valid prefix, and correct where needed. Repeat from the accepted continuation.',takeaway:'The exact acceptance algorithm matters: proper speculative sampling can preserve the main model’s target distribution.',sim:'mtp',sections:[['Accepted prefixes save serial steps','When draft predictions agree sufficiently with the target model, several output tokens can be committed after one verification pass. Mismatches reduce the accepted prefix.'],['Speed depends on the workload','Drafting adds work. Acceptance, draft depth, batch size, cache updates and verification cost determine whether it pays off. The animation shows a conceptual prefix check, not the full probabilistic acceptance algorithm.']],refs:['super'],children:['inference']},
  output:{parent:'tokens',label:'The next-token distribution',title:'Turn the final vector into possibilities.',color:'gold',intro:`After the stack, the output projection produces a score for each vocabulary token. ${term('Softmax')} converts these scores, or logits, into a probability distribution.`,takeaway:'The model predicts tokens, one step at a time. Decoding chooses a token from the distribution and feeds it back in.',sim:'output',sections:[['Selection can vary','Greedy decoding takes the highest-probability token. Sampling draws from a distribution, often adjusted by temperature and filtering. The bars here are invented example probabilities.'],['The loop creates the continuation','Append the chosen token, update the model’s state and caches, then predict again. Super’s embedding and output weights are untied: they are separate learned matrices.']],refs:['config','attention'],children:['inference']},
  inference:{parent:'overview',label:'Memory & inference',title:'The prompt pass and the generation loop.',color:'blue',icon:'▦',intro:`${term('Prefill')} processes the prompt. ${term('Decode','Decoding')} then generates tokens while reusing Mamba state and the attention ${term('KV cache')}.`,takeaway:'The hybrid model keeps two kinds of memory: fixed-shape Mamba states and growing attention caches.',sim:'cache',children:['memory','precision'],sections:[['What persists between steps','Attention caches store earlier keys and values. Mamba caches hold the recurrent state and a small convolution history. Expert layers add compute but do not have their own history of every token.'],['Long context still has costs','A longer prompt needs more prefill work and larger attention caches in the eight attention layers. Published long-context capability reaches 1M tokens; the pinned Hugging Face config defaults to 262,144. Runtime limits can differ.']],refs:['config','mambaCode','super'],next:'training'},
  memory:{parent:'inference',label:'Scaling & cache costs',title:'Separate compute growth from cache growth.',color:'blue',intro:'Several different “quadratic” and “linear” claims are easy to mix up. Compare the same operation, with layer width and head counts held fixed.',takeaway:'Dense attention’s all-pairs work is quadratic over a full sequence; its KV cache grows linearly with token count.',sim:'cache',table:[['Quantity','Attention / GQA','Mamba-2'],['Full sequence mixing work','O(L²) for dense attention','O(L) at fixed dimensions'],['History cache during decode','O(L) keys and values','O(1) recurrent state + local history'],['One extra token’s mixing work','O(L) attention lookup','O(1) recurrent update']],sections:[['GQA reduces a constant factor','Fewer KV heads reduce the growing cache. They do not remove the dependence on sequence length. FlashAttention can avoid storing the full attention matrix; it does not remove the dense all-pairs arithmetic.'],['State size is not zero','Mamba’s cache can be sizable, especially with many heads and large state dimension. Its storage stays fixed as L grows. Hybrid runtime includes both cache types, model weights and other buffers.']],refs:['gqa','mambaCode','mamba'],children:['grouping']},
  precision:{parent:'inference',label:'NVFP4 & quantization',title:'Store numbers with fewer bits.',color:'gold',intro:`Lower precision can reduce weight bandwidth and storage, and accelerate supported operations. ${term('NVFP4')} uses 4-bit floating-point values with additional scaling information.`,takeaway:'Low precision changes numerical representation. It does not change which of the 88 layers are Mamba, attention or experts.',sim:'precision',sections:[['Training uses mixed precision','Super was trained with NVFP4 for many linear operations while keeping sensitive parts, including latent projections, at higher precision. Exact precision choices depend on training phase and operation.'],['Deployment formats are another choice','NVIDIA also provides BF16, FP8 and NVFP4 checkpoints with mixed precision where needed. Four bits per value is a raw ideal; scales and higher precision tensors add storage. A3B or A12B active counts do not describe the memory needed to store all weights.']],refs:['precision','super'],children:['family']},
  training:{parent:'overview',label:'How it learns',title:'Architecture is the machinery. Training shapes it.',color:'gold',intro:'A network with the right blocks still starts without useful behavior. Training adjusts its parameters using text prediction, examples of desired responses and feedback on generated behavior.',takeaway:'Pretraining builds general predictive ability; post-training steers how the model responds and uses that ability.',sim:'training',children:['pretraining','post-training'],sections:[['Training and inference use the same learned machinery','Training computes losses and updates weights. Inference fixes those weights and computes new activations, states and caches for a prompt.'],['Reasoning is generated computation','The model can generate intermediate reasoning tokens before its answer. That increases decode work. Architecture, training and the inference budget all influence the resulting behavior.']],refs:['recipes'],next:'family'},
  pretraining:{parent:'training',label:'Pretraining & long context',title:'Learn from predicting continuations.',color:'gold',intro:'Pretraining learns statistical structure from broad text, code, mathematics and other data. Next-token prediction provides a learning signal at many positions; Super also uses future-token prediction objectives.',takeaway:'Long-context ability needs training exposure and evaluation, in addition to a memory-efficient architecture.',flow:[['Examples','Broad token sequences'],['Predict','Next + future token objectives'],['Loss','Compare predictions to targets'],['Update','Adjust model parameters']],sections:[['Curriculum and context extension','NVIDIA describes a 25-trillion-token corpus and staged training. A later continuous-pretraining phase extends context. These training tokens are cumulative examples, not vocabulary size or the context of one prompt.'],['Open recipes have a scope','The released cookbook provides training workflows and an open data subset. It does not promise that running those recipes exactly reproduces the published checkpoint or all its evaluations.']],refs:['train'],children:['post-training']},
  'post-training':{parent:'training',label:'Examples & rewards',title:'Teach responses, then reward useful behavior.',color:'gold',intro:`${term('SFT','Supervised fine-tuning')} learns from desired response examples. ${term('RL','Reinforcement learning')} then uses feedback on generated attempts to update the model.`,takeaway:'Verifiable rewards can check things like program execution; preference rewards judge qualities that do not have one exact answer.',flow:[['SFT','Learn from example responses'],['Generate','Attempt tasks + tool use'],['Evaluate','Tests, verifiers, preferences'],['RL update','Increase rewarded behavior']],sections:[['Supervised examples','Fine-tuning examples include instructions and trajectories for reasoning and tool use. The model learns to produce appropriate token sequences in those contexts.'],['Feedback beyond imitation','NVIDIA describes multi-environment RL, software engineering RL and preference-based alignment. These are training processes, not extra neural layers that run inside each forward pass.']],refs:['sft','rl'],children:['mtp']},
  family:{parent:'overview',label:'Model family',title:'Same family. Different configurations.',color:'violet',intro:'This guide follows the text architecture of Nemotron 3 Super 120B-A12B. Nano and Ultra belong to the same family, but their dimensions and expert designs are not interchangeable.',takeaway:'Use a model’s paper and checkpoint config together. Family names, approximate parameter labels and runtime defaults tell different parts of the story.',sim:'family',sections:[['Parameter labels are rounded','Super is branded 120B-A12B. The report gives 120.6B total and 12.7B active including embeddings, or 12.1B active excluding them. Active parameters estimate per-token work; all stored parameters still occupy memory.'],['Scope of this field guide','Nano uses standard sparse MoE. Super and Ultra use LatentMoE, MTP and NVFP4 training. Later 3.5 and multimodal Omni variants are outside this walkthrough; their additional designs need their own model-specific guide.']],refs:['family','nano','super'],next:'sources'}
};
Object.assign(nodes, {
  'mamba-shape':{parent:'mamba',label:'Heads, groups & state shape',title:'Fixed shape can still mean a lot of numbers.',color:'mint',intro:'Mamba heads split the expanded features into parallel channels. Groups share the input-dependent write and read vectors across heads; they are distinct from attention’s key/value groups.',takeaway:'Super’s 128 heads each carry a 64 × 128 state matrix. That is 1,048,576 recurrent state values per Mamba layer.',flow:[['128 heads','Parallel state channels'],['64 features','Width within each head'],['128 state coordinates','Memory dimension'],['1,048,576 values','128 × 64 × 128']],sections:[['Eight write/read groups','Super’s config has 8 Mamba groups. In the implementation, B and C vectors are shared by the 16 heads within each group, while each head has its own state and timescale. Sharing reduces projection work.'],['Cache size is fixed with respect to context','At batch size 1, storing this recurrent state in 32-bit floating point uses 4 MiB per Mamba layer, or 160 MiB across 40 layers. This derived number excludes convolution history, weights, attention caches and runtime buffers.']],refs:['config','modelCode'],children:['state','cache-math']},
  balancing:{parent:'routing',label:'Router scores & balancing',title:'Select useful experts. Keep the workload healthy.',color:'violet',intro:`Super’s router applies ${term('Sigmoid','sigmoid')} to learned scores. ${term('Load balancing','Load balancing')} helps prevent most tokens from concentrating on a few experts.`,takeaway:'Choosing an expert and weighting its output are related steps, with a useful distinction in the implementation.',flow:[['Full-width input','Learned router projection'],['Sigmoid scores','Each lies between 0 and 1'],['Select top-22','Scores + correction bias'],['Weight outputs','Original selected scores, normalized']],sections:[['Selection bias is separate from output weight','The published implementation adds a stored correction bias for expert selection, then gathers the original sigmoid scores for the chosen experts. Those selected scores are normalized and multiplied by a routed scaling factor of 5.'],['Why balance training matters','Overloaded experts can bottleneck distributed execution; underused experts receive less learning signal. NVIDIA’s pretraining guide describes bias-based balancing together with an auxiliary balancing loss. These are training mechanisms, not extra attention heads.']],refs:['modelCode','train'],children:['expert']},
  position:{parent:'stack',label:'How it knows the order',title:'The recurrence carries sequence order.',color:'mint',intro:`Many Transformers explicitly encode token positions. Super omits ${term('Positional embedding','positional embeddings')} in its attention path; Mamba’s ordered recurrence makes token order affect the representations.`,takeaway:'Reading “dog bites person” and “person bites dog” produces different state histories, even with the same vocabulary pieces.',flow:[['Read in order','Token 1 → token 2 → token 3'],['Update memory','Each step depends on prior state'],['Contextual vectors','Different orders, different states'],['Attention anchors','Look up those ordered representations']],sections:[['Order enters the state update','Changing token order changes which inputs arrive before each recurrent update. Local causal convolution is also sensitive to the order of nearby inputs. Later attention receives representations already shaped by that history.'],['Inspect the operation, not just config field names','The pinned config contains rotary-related fields, but its attention forward method does not apply a rotary transformation. The actual code agrees with the report’s statement that positional embeddings are omitted.']],refs:['modelCode','super'],children:['mamba']},
  'cache-math':{parent:'memory',label:'Put numbers on the cache',title:'Count the elements before counting bytes.',color:'blue',intro:'Cache size depends on token count, head count, head width, batch size and stored precision. These calculations hold the Super architecture fixed and use batch size 1.',takeaway:'Assuming BF16 keys and values, Super’s eight attention layers together need 8 KiB of KV elements per cached token.',flow:[['2 · K and V','Two stored tensors'],['2 KV heads','128 coordinates each'],['8 attention layers','512 values per layer / token'],['BF16 · 2 bytes','8 KiB per token across layers']],sections:[['An explicit KV example','2 × 2 × 128 × 8 × 2 bytes = 8,192 bytes per token. At 262,144 tokens that is 2 GiB; at 1,048,576 tokens it is 8 GiB. These are derived tensor-storage examples, not measured device-memory requirements.'],['The rest still counts','Multiply by batch size for multiple sequences, subject to runtime sharing and layout. Different KV precision changes the byte count. Add Mamba state, convolution history, all model weights, intermediate buffers and runtime overhead to estimate device memory.']],refs:['config','modelCode'],children:['precision']}
});
nodes.mamba.children.push('mamba-shape');
nodes.stack.children.push('position');
nodes.routing.children.push('balancing');
nodes.memory.children.push('cache-math');
nodes.moe.refs.push('modelCode');
nodes.routing.refs.push('modelCode');
const colors = {mint:'#87edc3',blue:'#82b5ff',violet:'#bba1ff',gold:'#f3cf86'};
const order = ['tokens','stack','mamba','attention','moe','mtp','inference','training','family'];
const layerPattern = 'MEMEMEM*EMEMEMEM*EMEMEMEM*EMEMEMEMEM*EMEMEMEMEM*EMEMEMEMEM*EMEMEMEMEM*EMEMEMEM*EMEMEMEME';
let visited;
try { visited = new Set(JSON.parse(localStorage.getItem('nemotron-visited') || '[]')); } catch { visited = new Set(); }
let motionPaused = matchMedia('(prefers-reduced-motion: reduce)').matches;
let simTimer = null;
let currentId = 'overview';

function sourceLinks(refs) { return `<div class="source-line"><span>↗ Verified against</span>${refs.map(key => `<a href="${sources[key][1]}" target="_blank" rel="noopener noreferrer">${sources[key][0]}</a>`).join('<span>·</span>')}</div>`; }
function card(id, small=false) {
  const n = nodes[id];
  return `<a class="concept-card" href="#${id}" style="--card-color:${colors[n.color]}">${!small?`<div class="card-icon" aria-hidden="true">${n.icon||'↳'}</div>`:''}<div class="card-tag">${n.children?`${n.children.length} IDEAS INSIDE`:'UNDER THE HOOD'}</div><h3>${n.label}</h3><p>${n.card || n.takeaway}</p><div class="card-bottom"><span>${visited.has(id)?'Explore again':'Open this idea'}</span><span aria-hidden="true">↗</span></div></a>`;
}
function renderNav() {
  let active=currentId;while(nodes[active]&&!order.includes(active))active=nodes[active].parent;
  $('#course-nav').innerHTML = `<a class="nav-link ${currentId==='overview'?'active':''}" href="#overview"><span class="nav-number">◎</span>The big picture</a><div class="nav-group-label">FOLLOW THE TOKEN</div>${order.map((id,i)=>`<a class="nav-link ${id===active?'active':''}" href="#${id}"><span class="nav-number">${String(i+1).padStart(2,'0')}</span>${nodes[id].label}${visited.has(id)?'<span class="nav-visited" aria-label="Visited"></span>':''}</a>`).join('')}<div class="nav-group-label">REFERENCE</div><a class="nav-link ${currentId==='sources'?'active':''}" href="#sources"><span class="nav-number">↗</span>Sources &amp; scope</a>`;
}
function isAncestor(id,target) { if (id===target) return true; let seen=new Set(); while(nodes[target]&&!seen.has(target)){seen.add(target);target=nodes[target].parent;if(target===id)return true;} return false; }
function renderCrumbs(id) {
  const path=[]; let k=id;
  while(nodes[k]){path.unshift(k);k=nodes[k].parent;}
  $('#crumbs').innerHTML = `<a href="#overview">Field guide</a>${id==='overview'?'<span class="sep">/</span><span class="current">Overview</span>':id==='sources'?'<span class="sep">/</span><span class="current">Sources</span>':path.map((p,i)=>`<span class="sep">/</span>${i===path.length-1?`<span class="current">${nodes[p].label}</span>`:`<a href="#${p}">${nodes[p].label}</a>`}`).join('')}`;
}
function renderOverview() {
  return `<section class="hero-head"><div class="hero-top"><span class="eyebrow">ANATOMY OF A LANGUAGE MODEL</span><span class="pill"><span class="dot"></span>NVIDIA · SUPER</span></div><h1>Big ideas.<br><span class="faint">Small steps.</span></h1><p class="lead">Understand Nemotron 3 from the inside out.<br>Follow a token, take apart a layer, and go as deep as you like.</p></section>
  <div class="stats"><div class="stat"><strong>120.6<span>B</span></strong><small>total learned parameters</small></div><div class="stat"><strong>12.7<span>B</span></strong><small>active per token, incl. embeddings</small></div><div class="stat"><strong>88 <span>layers</span></strong><small>three complementary building blocks</small></div></div>
  <section class="panel diagram-panel"><div class="panel-top"><h2>A token’s journey through Super</h2><span class="diagram-note">CLICK A BLOCK TO LOOK INSIDE</span></div><div class="architecture"><a class="pipeline-end" href="#tokens"><div class="token-stack"><span>The</span><span>sky</span><span>is</span></div><h3>Text → vectors</h3><p>Give each piece a representation</p></a><div class="stack-core"><span class="flow-dot" aria-hidden="true"></span><div class="core-title">THE HYBRID STACK · 88 LAYERS</div><a class="core-row mamba" href="#mamba"><span>≈ &nbsp;Mamba-2</span><small>× 40 &nbsp;↗</small></a><a class="core-row attention" href="#attention"><span>⌕ &nbsp;GQA attention</span><small>× 8 &nbsp;↗</small></a><a class="core-row expert" href="#moe"><span>⋮ &nbsp;LatentMoE</span><small>× 40 &nbsp;↗</small></a><div class="core-caption">Interleaved throughout the model</div></div><a class="pipeline-end" href="#output"><div class="output-bars" aria-hidden="true"><span style="height:16px"></span><span style="height:26px"></span><span style="height:50px"></span><span style="height:22px"></span><span style="height:11px"></span></div><h3>Predict what’s next</h3><p>A distribution over possible tokens</p></a></div><div class="arch-footer"><span>One stream. Memory, lookup and conditional computation.</span><a href="#stack">See the real layer map →</a></div></section>
  <div class="section-heading"><div><h2>Three ideas that make the hybrid work.</h2><p>Start with the intuition. Open a card to find the mechanics.</p></div><span>01 / THE CORE</span></div><div class="concept-grid">${['mamba','attention','moe'].map(id=>card(id)).join('')}</div>
  <div class="section-heading"><div><h2>Follow the rest of the journey.</h2><p>Build the foundations, then see how the machinery runs.</p></div><span>02 / THE CONNECTIONS</span></div><div class="concept-grid small-grid">${['tokens','mtp','inference','training'].map(id=>card(id,true)).join('')}</div>
  <div class="banner"><span class="banner-icon" aria-hidden="true">◇</span><div><h3>Nemotron 3 is a family.</h3><p>This walkthrough focuses on Super. Nano’s standard MoE and Ultra’s larger scale are explained too.</p></div><a href="#family">Compare variants ↗</a></div>
  <div class="section-heading"><div><h2>Your map for going deeper.</h2><p>Each branch opens another layer of understanding.</p></div><span>03 / THE CONCEPT TREE</span></div><div class="concept-tree">${order.map(id=>`<details class="tree-branch"><summary><span style="color:${colors[nodes[id].color]}">↳</span> ${nodes[id].label}<small>${nodes[id].children?.length||0} branches</small></summary><div><a href="#${id}">Open ${nodes[id].label} →</a>${(nodes[id].children||[]).map(child=>`<a href="#${child}">${nodes[child].label}<span>↗</span></a>`).join('')}</div></details>`).join('')}</div>${sourceLinks(['config','super'])}`;
}
function renderTopic(id) {
  const n=nodes[id];
  return `<section class="topic-head" style="--topic-color:${colors[n.color]}"><span class="eyebrow" style="color:${colors[n.color]}">${n.parent==='overview'?'FOLLOW THE TOKEN':'A CLOSER LOOK'} · ${n.label.toUpperCase()}</span><h1>${n.title}</h1><p class="lead">${n.intro}</p><div class="takeaway"><small>THE IDEA TO KEEP</small><p>${n.takeaway}</p></div></section>${simulation(n)}${n.table?`<div class="panel diagram-panel"><table class="comparison"><thead><tr>${n.table[0].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${n.table.slice(1).map(row=>`<tr>${row.map((x,i)=>i===0?`<th scope="row">${x}</th>`:`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}<div class="explanation-grid" style="--topic-color:${colors[n.color]}">${n.sections.map((s,i)=>`<section class="explanation"><div class="step-index">${String(i+1).padStart(2,'0')} / UNDERSTAND</div><h3>${s[0]}</h3><p>${s[1]}</p></section>`).join('')}</div>${n.children?`<div class="section-heading"><div><h2>Open the next layer.</h2><p>Choose the detail you want to understand next.</p></div><span>GO DEEPER ↓</span></div><div class="concept-grid small-grid">${n.children.map(id=>card(id,true)).join('')}</div>`:''}${n.quiz?quiz(n.quiz):''}${sourceLinks(n.refs)}<div class="next-topic"><a href="#${n.parent}">← ${n.parent==='overview'?'Back to the big picture':nodes[n.parent].label}</a>${n.next?`<a href="#${n.next}">Continue: ${nodes[n.next]?.label||'Sources'} →</a>`:'<a href="#overview">Explore another branch →</a>'}</div>`;
}
function quiz(q){return `<section class="question-box"><h3>One small check</h3><p>${q[0]}</p><div class="quiz-answers">${q[1].map((a,i)=>`<button class="quiz-answer" type="button" data-answer="${i}" data-correct="${q[2]}">${a}</button>`).join('')}</div><div class="quiz-feedback" aria-live="polite" data-feedback="${q[3]}"></div></section>`;}
function renderSources(){return `<section class="topic-head"><span class="eyebrow">THE REFERENCE DESK</span><h1>Built from the paper.<br>Checked against the code.</h1><p class="lead">The diagrams use original illustrative animations. Architecture dimensions and layer order come from NVIDIA’s report and public configuration.</p></section><div class="scope-note"><strong>Scope:</strong> Nemotron 3 Super’s text decoder is the main subject. The 88-layer pattern is pinned to configuration revision <code>a9f80fc…</code>. The report and checkpoint differ in how MTP training offsets and exported prediction modules are counted. We explain that distinction rather than treating the counts as interchangeable.</div>${Object.entries(sources).map(([key,s],i)=>`<article class="source-card"><span class="source-num">${String(i+1).padStart(2,'0')}</span><div><h3>${s[0]}</h3><p>${sourceDescriptions[key]||'Primary reference for the linked concepts.'}</p><a href="${s[1]}" target="_blank" rel="noopener noreferrer">Open source ↗</a></div></article>`).join('')}<div class="scope-note"><strong>How to read the animations:</strong> token pieces, state tiles, probabilities, routing choices and draft outcomes are teaching examples. They do not expose real model activations or measured benchmarks. Widths, expert counts, head counts and layer positions labeled “Super” are sourced facts. Attention’s KV cache grows linearly with context; quadratic scaling refers to dense all-pairs attention work.</div><a class="secondary-button" href="#overview">Return to the architecture →</a>`;}
const sourceDescriptions={super:'Model architecture, active parameter accounting, multi-token prediction, context extension and mixed precision. The main scientific reference for Super.',config:'A reproducible checkpoint snapshot: exact layer pattern, 4,096 model width, 32 query / 2 KV heads, 1,024 latent width and 512 top-22 experts.',mamba:'The original Mamba-2 paper explains structured state-space duality and the model’s efficient sequence computation.',mambaCode:'Implementation inspected for input projections, local convolution, selective state updates, gating and cache shapes.',ssd:'Tri Dao’s original explanation of the chunk algorithm, including the within-chunk and across-chunk views.',gqa:'The original grouped-query attention paper defines the relationship among multi-head, multi-query and grouped-query attention.',attention:'The original Transformer paper provides scaled dot-product attention, attention heads and causal masking.',latent:'The primary LatentMoE research paper develops the hardware-aware latent expert design.',family:'NVIDIA’s family overview distinguishes Nano, Super and Ultra and lists the technologies each uses.',recipes:'NVIDIA’s open cookbook links the training and deployment workflows. Its released data subset does not reproduce all original training data.',nano:'NVIDIA’s Nano reference gives its distinct 52-layer and standard MoE architecture.',blog:'The article you supplied motivates the Super walkthrough and its DGX Spark setting. Technical claims in the lessons use primary sources.',precision:'Official details on deployment quantization, precision formats and higher-precision exceptions.',train:'Official workflow for pretraining, curriculum, distributed training and long-context extension.',sft:'Official workflow for learning from examples during supervised fine-tuning.',rl:'Official workflow for reward-based post-training and verifiable tasks.'};

function panel(title, body, controls='', caption='', note='Illustrative mechanics · not real model activations') {
  return `<section class="panel diagram-panel"><div class="panel-top"><h2>${title}</h2>${controls}</div>${body}${caption?`<div class="sim-caption" id="sim-caption" aria-live="polite">${caption}</div>`:''}<div class="sim-disclaimer">${note}</div></section>`;
}
const words=['The','sky','is','bright','blue'];
const vector = (count, cls='') => `<div class="vector-bars ${cls}" aria-hidden="true">${Array.from({length:count},(_,i)=>`<i style="height:${23+(i*29%49)}px"></i>`).join('')}</div>`;
function simulation(n) {
  if(n.flow) return panel('The operation, one step at a time',`<div class="simple-flow">${n.flow.map((f,i)=>`${i?'<span class="sim-arrow" aria-hidden="true">→</span>':''}<div class="sim-box"><div class="label">${String(i+1).padStart(2,'0')}</div><strong>${f[0]}</strong><p>${f[1]}</p></div>`).join('')}</div>`,'','Follow the arrows from the incoming representation to the outgoing result.','Conceptual diagram · dimensions shown are Super configuration values where labeled');
  switch(n.sim){
    case 'tokens':return panel('Make the text numerical',`<div class="simple-flow"><div class="sim-box"><div class="label">TEXT</div><strong>The sky is blue.</strong></div><span class="sim-arrow">→</span><div class="sim-box"><div class="label">TOKEN PIECES · EXAMPLE</div><strong>The · sky · is · blue · .</strong></div><span class="sim-arrow">→</span><div class="sim-box"><div class="label">EMBEDDING LOOKUP</div><div class="vector-grid">${Array.from({length:32},(_,i)=>`<i style="opacity:${.2+(i*17%80)/100}"></i>`).join('')}</div><p>4,096 coordinates per token</p></div></div>`,`<a class="secondary-button" href="#embedding">Inside the lookup ↗</a>`,'The positions remain in order. Every token receives its own starting vector.');
    case 'embedding':return panel('Same starting token. Different context.',`<div class="segment" id="embedding-context"><button type="button" data-context="river" class="active">River bank</button><button type="button" data-context="money">Bank account</button></div><div class="simple-flow"><div class="sim-box"><div class="label">TOKEN</div><strong>bank</strong><p>Same vocabulary ID</p></div><span class="sim-arrow">→</span><div class="sim-box"><div class="label">STARTING EMBEDDING</div><div class="vector-grid">${Array.from({length:32},(_,i)=>`<i style="opacity:${.2+(i*17%80)/100}"></i>`).join('')}</div></div><span class="sim-arrow">→</span><div class="sim-box"><div class="label">AFTER CONTEXT MIXING</div><strong id="context-word">river edge</strong><div class="vector-grid" id="context-vector">${Array.from({length:32},(_,i)=>`<i style="opacity:${.2+(i*31%80)/100}"></i>`).join('')}</div></div></div>`,'','Select a context. The initial lookup stays the same; the later representation changes.');
    case 'stack':return panel('The actual 88-layer sequence',`<div class="layer-legend"><span><i class="legend-dot"></i>40 Mamba-2</span><span><i class="legend-dot" style="background:var(--violet)"></i>40 LatentMoE</span><span><i class="legend-dot" style="background:var(--blue)"></i>8 attention anchors</span></div><div class="layer-map">${[...layerPattern].map((c,i)=>`<button type="button" class="layer ${c==='*'?'A':c} ${i===0?'active':''}" data-layer="${i}" title="Layer ${i+1}: ${c==='M'?'Mamba-2':c==='E'?'LatentMoE':'GQA attention'}" aria-label="Layer ${i+1}: ${c==='M'?'Mamba-2':c==='E'?'LatentMoE':'GQA attention'}">${i+1}</button>`).join('')}</div><div class="layer-readout" id="layer-readout" aria-live="polite"></div>`,`<span class="diagram-note">SELECT ANY LAYER</span>`,'Read left to right, then continue on the next row. Each cell is one operation in the released pattern.','Exact pattern from the pinned NVIDIA config · embedding, output and auxiliary MTP paths are outside this 88-layer count');
    case 'mamba':return panel('Step a token through the memory',`<div class="token-row">${words.map((w,i)=>`<button class="token-button ${i===0?'selected':''}" data-token="${i}" type="button">${w}</button>`).join('')}</div><div class="mamba-stage"><div class="sim-box"><div class="label">CURRENT INPUT</div><strong id="mamba-token">The</strong><p class="flow-label">A token vector</p></div><span class="sim-arrow" aria-hidden="true">→</span><div class="sim-box state-box"><div class="label">RUNNING STATE</div><div class="state-grid">${Array.from({length:16},(_,i)=>`<span class="state-cell" style="opacity:${.2+(i*13%65)/100}"></span>`).join('')}</div><div class="state-footer">Same shape. New contents.</div></div><span class="sim-arrow readout-arrow" aria-hidden="true">→</span><div class="sim-box readout-box"><div class="label">READ OUT</div><strong id="mamba-output">y₁</strong><p class="flow-label">Features for the next layer</p></div></div><div class="state-math"><span>retain old state</span><span>+</span><span>write current input</span><span>=</span><span>new state</span></div>`,`<div class="sim-controls"><button class="secondary-button" type="button" id="mamba-reset">↺ Reset</button><button class="secondary-button" type="button" id="mamba-step">Step →</button><button class="primary-button" type="button" id="mamba-play">▶ Play</button></div>`,'<strong>Token 1 / 5:</strong> The incoming vector changes memory. Select a token or press Step.');
    case 'state':return panel('A one-coordinate toy recurrence',`<div class="range-control"><label for="retention">Retention a</label><input id="retention" type="range" min="0" max="100" value="80"><output id="retention-value" for="retention">0.80</output></div><div class="formula" id="state-equation"></div><div class="simple-flow"><div class="sim-box"><div class="label">OLD STATE</div><strong>h = 2</strong></div><span class="sim-arrow">→</span><div class="sim-box state-box"><div class="label">RETAIN + WRITE</div><strong id="new-state">2.60</strong><p>New state coordinate</p></div><span class="sim-arrow">→</span><div class="sim-box"><div class="label">READ OUT</div><strong id="state-readout">1.30</strong><p>c = 0.5 · D = 0 here</p></div></div>`,'','Change the retention factor. This toy uses a write contribution of 1 and a read factor of 0.5; real states have many coordinates.');
    case 'selectivity':return panel('Control a memory timescale',`<div class="range-control"><label for="delta">Time step Δ</label><input id="delta" type="range" min="5" max="200" value="30"><output id="delta-value" for="delta">0.30</output></div><div class="formula">a = exp(Δ · A)<small>This example fixes A = −1. Real Δ is learned from the token, not chosen by a user.</small></div><div class="retention-track"><span id="retention-fill"></span></div><div class="retention-readout"><strong id="decay-value">74%</strong><span>of the old state retained in this toy update</span></div>`,'','Move Δ upward: exp(−Δ) gets smaller, so old memory decays faster. B and C separately control writing and reading.');
    case 'attention':case 'grouping':return panel('Keep the queries. Share the keys and values.',`<div class="attention-stage"><div><div class="attn-matrix">${Array.from({length:25},(_,i)=>{const r=Math.floor(i/5),c=i%5;return `<div class="attn-cell ${c>r?'masked':r===4?'focus':''}">${c>r?'×':r===4?['.08','.12','.09','.26','.45'][c]:'·'}</div>`;}).join('')}</div><p class="matrix-title">Each row can look at its past · illustrative weights</p></div><div class="heads-viz"><p class="heads-label">32 distinct query heads</p><div class="heads">${Array.from({length:32},(_,i)=>`<span class="head ${i>=16?'group-two':''}"></span>`).join('')}</div><div class="group-lines" aria-hidden="true"></div><div class="kv-row" id="kv-row"></div><p class="matrix-title" id="kv-description">Two key/value heads, shared across 16 queries each</p></div></div>`,`<div class="segment"><button class="active" type="button" data-head-mode="gqa">Super GQA</button><button type="button" data-head-mode="mha">Ordinary MHA</button></div>`,'<strong>Super GQA:</strong> 32 queries still compare with context, while only 2 sets of keys and values are stored.');
    case 'qkv':case 'mask':return panel('Scores → normalized weights → a weighted sum',`<div class="token-row" id="score-tokens">${['The','sky','is','blue'].map((w,i)=>`<button class="token-button ${i===3?'selected':''}" type="button" data-score-token="${i}">${w}</button>`).join('')}</div><div class="score-bars" id="score-bars"></div><div class="formula">Attention(Q, K, V) = softmax(QKᵀ / √dₕ + mask) V<small>dₕ is the width of one attention head: 128 in Super. Match, scale, mask, normalize, mix.</small></div>`,'','Select a query position to see which keys are available. Future positions receive exactly zero weight.');
    case 'moe':case 'routing':case 'projection':return panel('Follow the routed expert path',`<div class="token-row">${['sky','code','river'].map((w,i)=>`<button type="button" class="token-button ${i===0?'selected':''}" data-route-token="${i}">${w}</button>`).join('')}</div><div class="moe-flow"><div>${vector(16)}<div class="flow-label">Full vector</div><div class="projection-tag">4,096</div></div><span class="sim-arrow">→</span><div>${vector(4,'narrow')}<div class="flow-label">Latent vector</div><div class="projection-tag">1,024</div></div><span class="sim-arrow dispatch-arrow">→</span><div class="expert-bank"><div class="router-label">FULL-WIDTH ROUTER → CHOOSE TOP-22</div><div class="expert-grid" aria-label="512 experts, of which 22 are selected">${Array.from({length:512},(_,i)=>`<span class="expert-dot" data-expert="${i}" aria-hidden="true"></span>`).join('')}</div><div class="expert-caption"><span>512 available experts</span><span>22 active per token</span></div></div><span class="sim-arrow restore-arrow">→</span><div class="restore">${vector(16)}<div class="flow-label">Combine + restore</div><div class="projection-tag">4,096</div></div></div><div class="shared-path"><span>+ full-width shared expert · every token</span></div>`,`<span class="diagram-note">SELECT A TOKEN</span>`,'The bright squares are the selected experts in this example. Routing depends on the token’s current context-dependent vector, not a fixed word category.');
    case 'mtp':return panel('An internal draft, checked by the main model',`<div class="mtp-track"><div class="mtp-token accepted">The sky<small>CONTEXT</small></div><span class="sim-arrow">→</span>${['is','bright','green'].map((w,i)=>`<div class="mtp-token" id="draft-${i}">${w}<small>NOT DRAFTED YET</small></div>`).join('')}</div><div class="verification-line" id="verification-line"><span>01 Draft</span><span>02 Verify together</span><span>03 Accept + correct</span></div>`,`<div class="sim-controls"><button type="button" class="secondary-button" id="mtp-reset">↺ Reset</button><button type="button" class="primary-button" id="mtp-action">Draft tokens →</button></div>`,'The main model has a continuation distribution. The auxiliary path proposes several candidate tokens.');
    case 'output':return panel('A next-token distribution · invented example',`<div class="output-distribution">${[['blue',.52],['clear',.24],['dark',.15],['…',.09]].map(([w,p],i)=>`<div class="distribution-row" data-output="${i}"><span>${w}</span><div><i style="width:${p*100}%"></i></div><strong>${Math.round(p*100)}%</strong></div>`).join('')}</div><div class="next-output">The sky is <strong id="chosen-output">blue</strong></div>`,`<div class="sim-controls"><button type="button" class="secondary-button" id="choose-greedy">Take highest</button><button type="button" class="primary-button" id="choose-sample">Sample again ↻</button></div>`,'Greedy selection chooses “blue.” Sampling can choose other tokens according to the displayed distribution.');
    case 'cache':return panel('More context. Two different kinds of history.',`<div class="range-control"><label for="context-length">Context length</label><input id="context-length" type="range" min="1" max="8" value="2"><output for="context-length" id="context-length-value">2K</output></div><div class="cache-viz"><div class="cache-column"><h3 style="color:var(--blue)">Attention · growing KV cache</h3><div class="cache-cells" id="kv-cache-cells"></div><p class="flow-label">2 KV heads per attention layer</p></div><div class="cache-column"><h3 style="color:var(--mint)">Mamba · fixed-shape state</h3><div class="cache-cells fixed">${Array.from({length:32},(_,i)=>`<span style="opacity:${.35+i*7%65/100}"></span>`).join('')}</div><p class="flow-label">Values update; shape stays fixed</p></div></div>`,'','Move the context slider. KV elements grow with tokens; the Mamba state retains the same shape. The block counts are visual units, not bytes.');
    case 'residual':return panel('Add a learned change to the stream',`<div class="residual-viz"><div class="sim-box"><div class="label">CURRENT VECTOR</div><strong>x</strong></div><div class="residual-path"><span class="residual-shortcut">shortcut · x</span><div class="residual-transform">RMSNorm → layer F</div></div><div class="sim-box state-box"><div class="label">UPDATED VECTOR</div><strong>x + F(norm(x))</strong></div></div><div class="formula">RMS(x) = √mean(xᵢ²)<small>Normalize using RMS with a small ε for numerical stability, then apply a learned scale.</small></div>`,'','The shortcut carries the current stream while the layer computes a change. Real implementation scaling is omitted from this conceptual diagram.');
    case 'precision':return panel('A smaller raw number format',`<div class="segment"><button type="button" data-bits="16" class="active">BF16 · 16 bits</button><button type="button" data-bits="8">FP8 · 8 bits</button><button type="button" data-bits="4">NVFP4 · 4 bits</button></div><div class="bit-strip" id="bit-strip">${Array.from({length:16},(_,i)=>`<span>${i%3?0:1}</span>`).join('')}</div><div class="precision-caption"><strong id="precision-size">2 bytes</strong><span>per raw value · additional scale data and mixed precision are excluded</span></div>`,'','Choose a format. Smaller representations reduce raw storage, but also have fewer representable values and require careful scaling.');
    case 'training':return panel('The broad training progression',`<div class="training-road"><a href="#pretraining" class="training-stop"><div class="stop-num">01 / PRETRAINING ↗</div><h3>Predict continuations</h3><p>Learn broad language, code and mathematical patterns.</p></a><a href="#post-training" class="training-stop"><div class="stop-num">02 / SUPERVISED EXAMPLES ↗</div><h3>Learn useful responses</h3><p>Follow instructions and imitate successful trajectories.</p></a><a href="#post-training" class="training-stop"><div class="stop-num">03 / FEEDBACK ↗</div><h3>Improve attempts</h3><p>Use task checks and preferences to reward useful behavior.</p></a></div>`,'','Open a stage to see what provides its learning signal.','Conceptual training progression · see official recipes for phase-specific schedules');
    case 'family':return panel('Where Super sits in the family',`<div class="family-tabs"><div class="family-card"><span class="eyebrow">NANO</span><h3>Compact hybrid</h3><p>Standard sparse MoE<br>Mamba-2 + GQA<br>52-layer backbone</p><strong>30B / A3B</strong><small>Rounded model label</small></div><div class="family-card focus"><span class="eyebrow">SUPER · THIS GUIDE</span><h3>Latent experts</h3><p>LatentMoE + MTP<br>Mamba-2 + GQA<br>88-layer backbone</p><strong>120B / A12B</strong><small>Rounded model label</small></div><div class="family-card"><span class="eyebrow">ULTRA</span><h3>Greater scale</h3><p>LatentMoE + MTP<br>Hybrid Mamba-attention<br>550B total model label</p><strong>550B / A55B</strong><small>Rounded model label</small></div></div>`,'','“B” means billion total parameters. “A” labels the approximate active parameter count per token.','Variant facts from NVIDIA · model labels are rounded, with embedding and auxiliary-module accounting varying by source');
    default:return '';
  }
}

function stopTimer(){if(simTimer!==null){clearInterval(simTimer);simTimer=null;}const b=$('#mamba-play');if(b)b.textContent='▶ Play';}
function setupSimulation(n){
  if(n.sim==='stack'){
    const update=(i)=>{const type=layerPattern[i],id=type==='M'?'mamba':type==='E'?'moe':'attention';$$('[data-layer]').forEach(b=>b.classList.toggle('active',Number(b.dataset.layer)===i));$('#layer-readout').innerHTML=`<div><strong style="color:${colors[nodes[id].color]}">Layer ${i+1} · ${nodes[id].label}</strong><p>${type==='M'?'Update the running sequence state.':type==='E'?'Transform this token using selected latent experts.':'Look back at earlier positions through grouped-query attention.'}</p></div><a href="#${id}">Look inside ↗</a>`;};
    $$('[data-layer]').forEach(b=>b.addEventListener('click',()=>update(Number(b.dataset.layer))));update(0);
  }
  if(n.sim==='mamba'){
    let position=0;
    const update=(p)=>{position=p;$$('[data-token]').forEach(b=>{b.classList.toggle('selected',Number(b.dataset.token)===p);b.classList.toggle('seen',Number(b.dataset.token)<p);});$('#mamba-token').textContent=words[p];$('#mamba-output').textContent=`y${['₁','₂','₃','₄','₅'][p]}`;$$('.state-cell').forEach((c,i)=>c.style.opacity=.15+(((i+1)*(p+3)*17)%80)/100);$('#sim-caption').innerHTML=`<strong>Token ${p+1} / 5: “${words[p]}”</strong> updates the same memory cells. Earlier inputs contribute through the state; the tile layout does not grow.`;$('#mamba-step').textContent=p===4?'Restart →':'Step →';};
    $$('[data-token]').forEach(b=>b.addEventListener('click',()=>{stopTimer();update(Number(b.dataset.token));}));$('#mamba-reset').addEventListener('click',()=>{stopTimer();update(0);});$('#mamba-step').addEventListener('click',()=>{stopTimer();update((position+1)%5);});$('#mamba-play').addEventListener('click',()=>{if(simTimer!==null){stopTimer();return;}if(motionPaused)setMotion(false);if(position===4)update(0);$('#mamba-play').textContent='Ⅱ Pause';simTimer=setInterval(()=>{if(position<4)update(position+1);else stopTimer();},1300);});
  }
  if(n.sim==='state'){
    const update=()=>{const a=Number($('#retention').value)/100,h=a*2+1;$('#retention-value').textContent=a.toFixed(2);$('#state-equation').innerHTML=`h<sub>new</sub> = <span class="formula-term">${a.toFixed(2)} × 2</span> + <span class="formula-term">1</span> = ${h.toFixed(2)}<small>retain old memory + write current input</small>`;$('#new-state').textContent=h.toFixed(2);$('#state-readout').textContent=(h*.5).toFixed(2);};$('#retention').addEventListener('input',update);update();
  }
  if(n.sim==='selectivity'){
    const update=()=>{const d=Number($('#delta').value)/100,a=Math.exp(-d);$('#delta-value').textContent=d.toFixed(2);$('#retention-fill').style.width=`${a*100}%`;$('#decay-value').textContent=`${Math.round(a*100)}%`;};$('#delta').addEventListener('input',update);update();
  }
  if(['attention','grouping'].includes(n.sim)){
    const update=(mode)=>{$$('[data-head-mode]').forEach(b=>b.classList.toggle('active',b.dataset.headMode===mode));const count=mode==='gqa'?2:32;$('#kv-row').innerHTML=Array.from({length:count},(_,i)=>`<span class="kv-head">K${i+1} / V${i+1}</span>`).join('');$('#kv-description').textContent=mode==='gqa'?'Two key/value heads, shared across 16 queries each':'32 key/value heads, one pair for each query head';$('#sim-caption').innerHTML=mode==='gqa'?'<strong>Super GQA:</strong> 2 KV heads use 1/16 of the KV elements of the shown 32-KV-head baseline.':'<strong>Ordinary MHA baseline:</strong> 32 separate key/value heads. The number of query heads is still 32.';};$$('[data-head-mode]').forEach(b=>b.addEventListener('click',()=>update(b.dataset.headMode)));update('gqa');
  }
  if(['qkv','mask'].includes(n.sim)){
    const update=(position)=>{const scores=[.7,1.2,.4,2.1],sum=scores.slice(0,position+1).reduce((s,v)=>s+Math.exp(v),0);$$('[data-score-token]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.scoreToken)===position));$('#score-bars').innerHTML=scores.map((v,i)=>`<div class="score-row"><span>${['The','sky','is','blue'][i]}</span><div><i style="width:${i>position?0:Math.exp(v)/sum*100}%"></i></div><strong>${i>position?'masked':`${Math.round(Math.exp(v)/sum*100)}%`}</strong></div>`).join('');$('#sim-caption').innerHTML=`Query at <strong>“${['The','sky','is','blue'][position]}”</strong> can use ${position+1} position${position===0?'':'s'}. The displayed available weights sum to 100% before rounding.`;};$$('[data-score-token]').forEach(b=>b.addEventListener('click',()=>update(Number(b.dataset.scoreToken))));update(3);
  }
  if(['moe','routing','projection'].includes(n.sim)){
    const update=(token)=>{const selected=new Set(Array.from({length:22},(_,i)=>(i*23+token*97+11)%512));$$('[data-route-token]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.routeToken)===token));$$('[data-expert]').forEach(e=>e.classList.toggle('on',selected.has(Number(e.dataset.expert))));$('#sim-caption').innerHTML=`<strong>22 of 512 experts selected</strong> for this example “${['sky','code','river'][token]}” vector. The shared expert also runs. These selections are illustrative, not fixed word-to-expert assignments.`;};$$('[data-route-token]').forEach(b=>b.addEventListener('click',()=>update(Number(b.dataset.routeToken))));update(0);
  }
  if(n.sim==='mtp'){
    let stage=0;
    const update=()=>{for(let i=0;i<3;i++){const e=$(`#draft-${i}`);e.className=`mtp-token ${stage===1?'draft':stage===2?(i<2?'accepted':'rejected'):stage===3?'accepted':''}`;e.innerHTML=`${stage===3&&i===2?'blue':['is','bright','green'][i]}<small>${stage===0?'NOT DRAFTED YET':stage===1?'CANDIDATE':stage===2?(i<2?'ACCEPTED':'REJECTED'):(i<2?'ACCEPTED':'CORRECTED')}</small>`;}$('#mtp-action').textContent=['Draft tokens →','Verify together →','Accept + correct →','Try again ↻'][stage];$('#sim-caption').innerHTML=['The internal prediction path is ready to draft candidate tokens.','<strong>Draft:</strong> the auxiliary path proposes “is bright green.” These are candidates.','<strong>Verification:</strong> this toy check accepts a two-token prefix and rejects the third candidate.','<strong>Continuation:</strong> commit the accepted prefix and a corrected token. Then begin the next draft.'][stage];$$('#verification-line span').forEach((e,i)=>e.classList.toggle('active',stage===i+1));};$('#mtp-action').addEventListener('click',()=>{stage=(stage+1)%4;update();});$('#mtp-reset').addEventListener('click',()=>{stage=0;update();});
  }
  if(n.sim==='cache'){
    const update=()=>{const l=Number($('#context-length').value);$('#context-length-value').textContent=`${l}K`;$('#kv-cache-cells').innerHTML=Array.from({length:l*16},()=>'<span></span>').join('');$('#sim-caption').innerHTML=`<strong>${l}K illustrative context:</strong> the blue KV cache grows linearly with token count. The green recurrent state has the same number of cells, with changing values.`;$$('.cache-cells.fixed span').forEach((c,i)=>c.style.opacity=.2+((i+3)*l*7%75)/100);};$('#context-length').addEventListener('input',update);update();
  }
  if(n.sim==='embedding')$$('[data-context]').forEach(b=>b.addEventListener('click',()=>{const river=b.dataset.context==='river';$$('[data-context]').forEach(e=>e.classList.toggle('active',e===b));$('#context-word').textContent=river?'river edge':'financial account';$$('#context-vector i').forEach((e,i)=>e.style.opacity=.2+(i*(river?31:19)%80)/100);}));
  if(n.sim==='precision')$$('[data-bits]').forEach(b=>b.addEventListener('click',()=>{const bits=Number(b.dataset.bits);$$('[data-bits]').forEach(e=>e.classList.toggle('active',e===b));$('#bit-strip').innerHTML=Array.from({length:bits},(_,i)=>`<span>${i%3?0:1}</span>`).join('');$('#precision-size').textContent=`${bits/8} ${bits===8?'byte':'bytes'}`;}));
  if(n.sim==='output'){
    const choose=(i)=>{$$('[data-output]').forEach(e=>e.classList.toggle('chosen',Number(e.dataset.output)===i));$('#chosen-output').textContent=['blue','clear','dark','…'][i];};$('#choose-greedy').addEventListener('click',()=>choose(0));$('#choose-sample').addEventListener('click',()=>{const p=Math.random();choose(p<.52?0:p<.76?1:p<.91?2:3);});choose(0);
  }
}

function render(){
  stopTimer(); const id=location.hash.slice(1)||'overview';currentId=id==='sources'||id==='overview'||nodes[id]?id:'overview';
  if(nodes[currentId]){visited.add(currentId);try{localStorage.setItem('nemotron-visited',JSON.stringify([...visited]));}catch{}}
  $('#app').innerHTML=currentId==='overview'?renderOverview():currentId==='sources'?renderSources():renderTopic(currentId);
  $('#app').classList.remove('fade-in');void $('#app').offsetWidth;$('#app').classList.add('fade-in');renderNav();renderCrumbs(currentId);if(nodes[currentId])setupSimulation(nodes[currentId]);
  document.title=`${currentId==='overview'?'Inside Nemotron 3':currentId==='sources'?'Sources':nodes[currentId].label} · Interactive field guide`;
  window.scrollTo({top:0,behavior:'instant'});
}
function renderGlossary(filter=''){
  const q=filter.trim().toLowerCase();const found=glossary.filter(g=>g.join(' ').toLowerCase().includes(q));
  $('#glossary-list').innerHTML=found.length?found.map(([key,exp,definition])=>`<details class="glossary-item" data-glossary="${key}"><summary>${key}</summary><p class="expansion">${exp}</p><p>${definition}</p></details>`).join(''):'<p class="glossary-foot">No matching term. Try a word such as “memory,” “expert,” or “head.”</p>';
}
function openGlossary(key){
  $('#glossary-search').value='';renderGlossary();if(matchMedia('(max-width:1250px)').matches)toggleGlossary(true);const detail=$$('.glossary-item').find(e=>e.dataset.glossary===key);if(detail){detail.open=true;detail.scrollIntoView({block:'nearest',behavior:motionPaused?'instant':'smooth'});$('summary',detail).focus({preventScroll:true});}
}
let glossaryReturnFocus=null;
function toggleGlossary(open){const panel=$('#glossary-panel');panel.classList.toggle('open',open);$('#glossary-toggle').setAttribute('aria-expanded',String(open));$('#mobile-scrim').hidden=!open;if(open){glossaryReturnFocus=document.activeElement;$('#glossary-search').focus();}else if(glossaryReturnFocus){glossaryReturnFocus.focus({preventScroll:true});}}
function setMotion(paused){motionPaused=paused;document.body.classList.toggle('paused',paused);$('#motion-toggle').setAttribute('aria-pressed',String(paused));$('#motion-toggle').innerHTML=paused?'◉ <span>Resume motion</span>':'◉ <span>Pause motion</span>';if(paused)stopTimer();}
document.addEventListener('click',(event)=>{
  const t=event.target.closest('[data-term]');if(t)openGlossary(t.dataset.term);
  const a=event.target.closest('.quiz-answer');if(a){const correct=a.dataset.answer===a.dataset.correct;$$('.quiz-answer',a.parentElement).forEach(b=>b.classList.remove('correct','incorrect'));a.classList.add(correct?'correct':'incorrect');const f=$('.quiz-feedback',a.closest('.question-box'));f.textContent=correct?`Yes. ${f.dataset.feedback}`:'Try again. Use the diagram above to check your intuition.';}
});
$('#glossary-search').addEventListener('input',e=>renderGlossary(e.target.value));
$('#glossary-toggle').addEventListener('click',()=>toggleGlossary(!$('#glossary-panel').classList.contains('open')));
$('#glossary-close').addEventListener('click',()=>toggleGlossary(false));
$('#mobile-scrim').addEventListener('click',()=>toggleGlossary(false));
$('#motion-toggle').addEventListener('click',()=>setMotion(!motionPaused));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#glossary-panel').classList.contains('open'))toggleGlossary(false);});
window.addEventListener('hashchange',()=>{render();$('#app').focus({preventScroll:true});});
setMotion(motionPaused);renderGlossary();render();
